import {videoMIDITargets} from './video-midi.js';
import {videoEffectCatalog} from './video-effects-catalog.js';
const $=s=>document.querySelector(s),assert=(x,m)=>{if(!x)throw Error(m);},sleep=ms=>new Promise(r=>setTimeout(r,ms));
const sourceFiles=['app.js','panels.js','midi.js','video-midi.js','video-controls.js','video.js','video-pipeline.js','video-effects-catalog.js','video-transitions.js','video-midi-harness.js','index.html'];
const sha=async b=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',b)),x=>x.toString(16).padStart(2,'0')).join('');
const bounded=(p,label,ms=10000)=>{let timer;return Promise.race([p,new Promise((_,reject)=>timer=setTimeout(()=>reject(Error(label+' timed out')),ms))]).finally(()=>clearTimeout(timer));};
const hashes=()=>bounded(Promise.all(sourceFiles.map(async p=>{const r=await fetch(p);assert(r.ok,'Source unavailable '+p);return[p,await sha(await r.arrayBuffer())];})).then(Object.fromEntries),'Source identities');
async function until(fn,label,ms=10000){const end=performance.now()+ms;while(!fn()){assert(performance.now()<end,label+' timed out');await sleep(20);}}
function field(s,value){const e=$(s);assert(e,'Missing '+s);e.value=String(value);e.dispatchEvent(new Event(e.tagName==='SELECT'?'change':'input',{bubbles:true}));}
function click(s){assert($(s),'Missing '+s);$(s).click();}
const storedKey='openplay-video-midi-check-v1';let prior;try{prior=JSON.parse(localStorage.getItem(storedKey)||'null');}catch{}
let app,url;
function closeModal(){if($('#modal').open)click('#modal-close');}
function mapper(){if($('#modal').open&&!$('#midi-target'))closeModal();if(!$('#modal').open)click('[data-panel="midi"]');assert($('#midi-target'),'Actual mapper missing');}
function publish(r){$('#video-midi-results').textContent=JSON.stringify({...r,frames:r.frames.map(({dataURL,...f})=>({...f,dataURL:'Complete PNG retained in download'})),fixtures:r.fixtures.map(({base64,...f})=>({...f,base64:'Complete original fixture retained in download'}))},null,2);$('#video-midi-status').textContent=`${r.phase}: ${r.checks.filter(x=>x.passed).length}/${r.checks.length} checks; ${r.fatalErrors.length} fatal; ${r.completed?'scoped phase passed':'acceptance incomplete'}`;if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(new Blob([JSON.stringify(r,null,2)],{type:'application/json'}));const a=$('#video-midi-download');a.href=url;a.download=`video-midi-browser-${r.phase}-results.json`;a.hidden=false;}
async function run(){const {state,engine}=app,v=state.video,r={phase:prior?'restored':'initial',startedAt:new Date().toISOString(),scope:'Actual app DOM callbacks/mapper/persistence/GPU canvas, synthetic standard messages. Placeholder pixel tests plus generated local video decode/save/recall/association. No hardware/native/vendor acceptance.',checks:[],frames:[],fixtures:[],fatalErrors:[],sourceBefore:{},completed:false};
 async function check(name,fn){const e={};try{await fn(e);r.checks.push({name,passed:true,evidence:e});}catch(error){r.checks.push({name,passed:false,evidence:e,error:error.message,stack:error.stack});}publish(r);}
 function message(number,value,type='CC'){mapper();field('#midi-type',type);field('#midi-channel',1);field('#midi-number',number);field('#midi-test-value',value);click('#midi-send');}
 async function add(target,number,encoding='7-bit absolute',learn=false){mapper();field('#midi-target',target);assert($('#midi-target').value===target,'Actual target missing '+target);field('#midi-encoding',encoding);field('#midi-type','CC');field('#midi-channel',1);field('#midi-number',number);if(learn){const before=JSON.stringify(v);click('#midi-learn');message(number,127);await until(()=>$('#midi-learn').textContent==='Learn next message','Learn capture');assert(JSON.stringify(v)===before,'Learning executed Video action');}const count=state.mappings.length;click('#midi-add');assert(state.mappings.length===count+1,'Mapping not added');return structuredClone(state.mappings.at(-1));}
 async function set(number,value,predicate,label){message(number,value);await until(predicate,label);await sleep(90);}
 async function button(number,predicate,label){message(number,0);message(number,127);await until(predicate,label);await sleep(90);}
 const audio=()=>({cross:engine.cross,levels:engine.nodes.map(n=>n.level),decks:state.decks.map(d=>({track:d.track?.id,playing:d.playing,rate:d.rate,keyShift:d.keyShift||0}))});
 async function frame(label){await sleep(120);const c=$('#video-master');assert(c,'Video output not present');const dataURL=c.toDataURL('image/png'),bytes=Uint8Array.from(atob(dataURL.split(',')[1]),x=>x.charCodeAt(0));const out={label,width:c.width,height:c.height,pixel:[...c.getContext('2d').getImageData(c.width/2,c.height/2,1,1).data],sha256:await sha(bytes),dataURL};r.frames.push(out);return{label,pixel:out.pixel,sha256:out.sha256};}
 const expect=(actual,expected)=>assert(actual.every((n,i)=>Math.abs(n-expected[i])<=2),'Pixel mismatch '+JSON.stringify({actual,expected}));
 try{
  r.sourceBefore=await hashes();await engine.resume();engine.audioMonitor.mutePhysical(true);await until(()=>engine.audioMonitor.snapshot().physicalMuted,'Observed physical mute',2000);
  r.physicalOutputMuted=true;r.audioBefore=audio();
  await check('Actual mapper lists Video controls without losing four-deck Key Shift',async e=>{mapper();e.targets=[...$('#midi-target').options].map(x=>x.value);assert(videoMIDITargets.every(x=>e.targets.includes(x.target)),'Video MIDI targets missing');assert([1,2,3,4].every(i=>e.targets.includes(`Deck ${i} key shift`)),'Key Shift target lost');});
  if(!r.checks[0].passed)throw Error('Stop before state mutation: actual Video target integration is missing.');
  closeModal();if(state.panel!=='video')click('[data-panel="video"]');await until(()=>$('#video-pipeline-state')?.textContent.includes('processed frames'),'Real Video frames');
  if(!prior){
   await check('Learn captures a Video target without dispatch and preserves earlier generic mappings',async e=>{assert(state.mappings.length===0,'Initial phase requires isolated origin');await add('Library browse',1,'Relative two’s complement');await add('Deck 1 key shift',16);e.mapping=await add('Video crossfader',20,'7-bit absolute',true);assert(state.mappings[0].target==='Library browse'&&state.mappings[1].target==='Deck 1 key shift','Prior mappings lost');});
   await check('Crossfader and channel links relinquish only their Video owners',async e=>{await add('Video crossfader link',21);await add('Video left opacity link',22);await add('Video right opacity link',23);await button(21,()=>!v.crossLinked,'Cross unlink');await button(22,()=>!v.channelOpacityLinked[0],'Left unlink');await button(23,()=>!v.channelOpacityLinked[1],'Right unlink');await add('Video left opacity',24);await add('Video right opacity',25);await set(24,127,()=>v.channelOpacity[0]===1,'Left opacity');await set(25,127,()=>v.channelOpacity[1]===1,'Right opacity');e.links={cross:v.crossLinked,opacity:[...v.channelOpacityLinked],playback:v.linked};});
   await check('Actual crossfader endpoints render both live placeholder sources',async e=>{await set(20,0,()=>v.cross===-1,'Left endpoint');e.left=await frame('left-endpoint');expect(e.left.pixel,[23,50,59,255]);await set(20,127,()=>v.cross===1,'Right endpoint');e.right=await frame('right-endpoint');expect(e.right.pixel,[51,33,39,255]);});
   await check('Channel opacity maps to actual GPU alpha independently',async e=>{await set(20,0,()=>v.cross===-1,'Left');await set(24,0,()=>v.channelOpacity[0]===0,'Opacity zero');e.zero=await frame('left-zero');expect(e.zero.pixel,[0,0,0,0]);await set(24,64,()=>v.channelOpacity[0]===64/127,'Opacity partial');e.partial=await frame('left-partial');expect(e.partial.pixel,[23,50,59,255*64/127]);await set(24,127,()=>v.channelOpacity[0]===1,'Opacity reset');assert(v.channelOpacity[1]===1,'Other channel changed');});
   await check('Relative transition selection changes actual mixed pixels and returns to the baseline',async e=>{await add('Video transition select',26,'Relative two’s complement');await set(20,64,()=>v.cross===64/127*2-1,'Mixed sources');const before=v.transition;e.before=await frame('transition-baseline-middle');message(26,2);await until(()=>v.transition==='Upfaders Only','Next transition');e.next=v.transition;e.changed=await frame('transition-upfaders-only');assert(e.changed.pixel[0]>e.before.pixel[0]+15,'Selected transition did not change actual RGB');message(26,126);await until(()=>v.transition===before,'Previous transition');e.restored=await frame('transition-restored-middle');expect(e.restored.pixel,e.before.pixel);});
   await check('Every channel/master FX slot receives independent selection, amount and press-edge changes',async e=>{e.slots=[];let number=30;const index=videoEffectCatalog.findIndex(x=>x.name==='Negative'),selectValue=Math.ceil((index+.25)/videoEffectCatalog.length*127);for(const side of ['left','right','master'])for(const slot of [1,2]){const selectN=number++,amountN=number++,onN=number++;await add(`Video ${side} FX ${slot} select`,selectN);await add(`Video ${side} FX ${slot} amount`,amountN);await add(`Video ${side} FX ${slot} on`,onN);await set(selectN,selectValue,()=>v.fx[side][slot-1].name==='Negative','FX selection');await set(amountN,127,()=>v.fx[side][slot-1].value===1,'FX amount');if(side==='right')await set(20,127,()=>v.cross===1,'Right endpoint');else await set(20,0,()=>v.cross===-1,'Left endpoint');await button(onN,()=>v.fx[side][slot-1].on,'FX on');assert(Object.entries(v.fx).every(([target,specs])=>specs.every((x,i)=>x.on===(target===side&&i===slot-1))),'FX command changed another slot');const image=await frame(`${side}-slot${slot}-negative`);assert(image.pixel[0]>190&&image.pixel[1]>190,'Effect did not change rendered pixels');message(onN,127);await sleep(50);assert(v.fx[side][slot-1].on,'Held button toggled twice');await button(onN,()=>!v.fx[side][slot-1].on,'FX off');e.slots.push({side,slot,...image});}});
   await check('Directional MIDI fade reaches actual opposite output and repeated press does not restart',async e=>{await add('Video fade speed',50);await add('Video fade right',51);await set(50,127,()=>v.autoCrossfadeSeconds===.25,'Fast speed');await set(20,0,()=>v.cross===-1,'Fade start');message(51,0);message(51,127);message(51,127);await until(()=>v.cross===1,'Directional fade endpoint',3000);e.end=await frame('fade-right-end');expect(e.end.pixel,[51,33,39,255]);});
   await check('Remove and reassign change actual mapper dispatch without removing legacy mappings',async e=>{mapper();const i=state.mappings.findIndex(x=>x.target==='Video left opacity');assert(i>=0,'Mapping missing');click(`[data-midi-remove="${i}"]`);message(24,0);await sleep(80);assert(v.channelOpacity[0]===1,'Removed mapping still dispatches');const j=state.mappings.findIndex(x=>x.target==='Video right opacity');click(`[data-midi-reassign="${j}"]`);field('#midi-number',27);click('#midi-add');assert(!state.mappings.some(x=>x.target==='Video right opacity'&&x.number===25),'Reassign retained old mapping');message(25,0);await sleep(80);assert(v.channelOpacity[1]===1,'Old input still dispatches');await set(27,0,()=>v.channelOpacity[1]===0,'Reassigned input');await set(27,127,()=>v.channelOpacity[1]===1,'Reassigned reset');assert(state.mappings[0].target==='Library browse','Legacy mapping lost');e.mappings=structuredClone(state.mappings);});
   await check('Editing an unrelated mapping does not rearm a held Video toggle',async e=>{await button(21,()=>v.crossLinked,'Link on');await add('Video playback link',60);message(21,127);await sleep(120);assert(v.crossLinked,'Unrelated Add rearmed held control');await button(21,()=>!v.crossLinked,'Link off');e.heldEdgePreserved=true;});
   await check('MIDI save and recall operate on a genuinely decoded generated video',async e=>{
    const c=document.createElement('canvas');c.width=320;c.height=180;c.getContext('2d').fillStyle='#ff0000';c.getContext('2d').fillRect(0,0,320,180);
    const stream=c.captureStream(30),chunks=[],recorder=new MediaRecorder(stream,{mimeType:'video/webm;codecs=vp8'});let painted=0,request;const paint=()=>{const ctx=c.getContext('2d');ctx.fillStyle='#ff0000';ctx.fillRect(0,0,320,180);ctx.fillStyle=`rgb(${painted++%255},255,0)`;ctx.fillRect(0,0,16,16);request=requestAnimationFrame(paint);};
    recorder.ondataavailable=event=>{if(event.data.size)chunks.push(event.data);};
    const stopped=new Promise((resolve,reject)=>{recorder.onstop=resolve;recorder.onerror=event=>reject(event.error||Error('Fixture recording failed'));});
    try{recorder.start();paint();await sleep(600);recorder.stop();await bounded(stopped,'Fixture recorder');}finally{cancelAnimationFrame(request);for(const track of stream.getTracks())track.stop();}
    const blob=new Blob(chunks,{type:recorder.mimeType}),bytes=new Uint8Array(await blob.arrayBuffer());let binary='';for(const b of bytes)binary+=String.fromCharCode(b);
    r.fixtures.push({name:'video-midi-red.webm',mime:blob.type,paintedFrames:painted,requestedDurationMs:600,bytes:bytes.length,sha256:await sha(bytes),base64:btoa(binary)});
    closeModal();const input=$('[data-video-file="0"]'),transfer=new DataTransfer();transfer.items.add(new File([blob],'video-midi-red.webm',{type:blob.type}));input.files=transfer.files;input.dispatchEvent(new Event('change',{bubbles:true}));
    await until(()=>!input.disabled&&$('#video-status-0').textContent.includes('video-midi-red.webm'),'Actual local video decode');
    await set(20,0,()=>v.cross===-1,'Decoded clip side');e.original=await frame('decoded-red');expect(e.original.pixel,[255,0,0,255]);
    await add('Video left save FX',52);await add('Video left recall FX',53);await button(52,()=>v.savedVideoFX.length===1,'Real FX save');e.saved=structuredClone(v.savedVideoFX);
    await button(32,()=>v.fx.left[0].on,'Edit saved FX');e.changed=await frame('decoded-red-negative');expect(e.changed.pixel,[0,255,255,255]);
    await button(53,()=>!v.fx.left[0].on,'Real saved FX recall');e.recalled=await frame('decoded-red-recalled');expect(e.recalled.pixel,[255,0,0,255]);
   });
   await check('MIDI association and removal are visible in the real Media Crate workflow',async e=>{
    await add('Video left associate',54);await add('Video left unassociate',55);await add('Video open media',56);
    message(54,0);message(54,127);await sleep(150);message(56,0);message(56,127);await until(()=>$('#video-media-associations')?.textContent.includes('video-'),'Association diagnostics');
    e.associated=JSON.parse($('#video-media-associations').textContent);assert(e.associated[0].assetId&&e.associated[1].assetId===null,'Wrong association side');
    closeModal();message(55,0);message(55,127);await sleep(100);message(56,0);message(56,127);await until(()=>$('#video-media-associations'),'Removal diagnostics');
    e.removed=JSON.parse($('#video-media-associations').textContent);assert(e.removed.every(x=>x.assetId===null),'Association removal failed');closeModal();
   });
   await check('Mapped panel commands open their actual controls and 14-bit command Add is rejected',async e=>{
    for(const [target,number,selector]of [['Video open FX',57,'#video-fx-target'],['Video open overlays',58,'#video-overlay-target'],['Video open panel',59,'#video-master']]){
     await add(target,number);message(number,0);message(number,127);await until(()=>$(selector),'Mapped '+target);closeModal();
    }
    mapper();const count=state.mappings.length;field('#midi-target','Video crossfader link');field('#midi-encoding','14-bit absolute');field('#midi-number',0);click('#midi-add');assert(state.mappings.length===count,'Unsafe two-byte command mapping accepted');e.rejected=true;
   });
  }else{
   await check('Actual reload restored all saved generic and Video mappings',async e=>{assert(prior.completed&&prior.savedMappings.length>20,'No accepted initial phase');assert(JSON.stringify(state.mappings)===JSON.stringify(prior.savedMappings),'Saved mapping mismatch');e.count=state.mappings.length;});
   await check('Restored MIDI fader and FX mappings render without relearning',async e=>{await set(20,0,()=>v.cross===-1,'Restored left');e.left=await frame('restored-left');expect(e.left.pixel,[23,50,59,255]);await set(20,127,()=>v.cross===1,'Restored right');e.right=await frame('restored-right');expect(e.right.pixel,[51,33,39,255]);await button(32,()=>v.fx.left[0].on,'Restored FX on');await set(20,0,()=>v.cross===-1,'Restored FX source');e.fx=await frame('restored-left-negative');assert(e.fx.pixel[0]>190,'Restored FX not rendered');await button(32,()=>!v.fx.left[0].on,'Restored FX off');});
  }
  await check('All Video MIDI operations preserve actual audio settings and stopped transports',async e=>{e.before=r.audioBefore;e.after=audio();assert(JSON.stringify(e.before)===JSON.stringify(e.after),'Video MIDI mutated audio settings');});
  r.savedMappings=structuredClone(state.mappings);
 }catch(error){r.fatalErrors.push({message:error.message,stack:error.stack});}
 finally{for(const d of state.decks)engine.pause(d);try{await bounded(engine.ctx.close(),'Context close');}catch(e){r.fatalErrors.push({phase:'close',message:e.message});}try{r.sourceAfter=await hashes();r.sourceStable=JSON.stringify(r.sourceAfter)===JSON.stringify(r.sourceBefore);}catch(e){r.sourceStable=false;r.fatalErrors.push({phase:'sourceAfter',message:e.message});}r.completed=r.checks.length===(prior?4:14)&&r.checks.every(x=>x.passed)&&!r.fatalErrors.length&&r.sourceStable;r.finishedAt=new Date().toISOString();publish(r);if(!prior&&r.completed)localStorage.setItem(storedKey,JSON.stringify({completed:r.completed,savedMappings:r.savedMappings}));}
}
async function init(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const e of [...parsed.body.children])if(e.tagName!=='SCRIPT')document.body.append(e);await import('./app.js');await until(()=>window.openPlay?.state.decks[0].track,'Actual app');app=window.openPlay;$('#video-midi-run').disabled=false;$('#video-midi-run').textContent=prior?'Run restored Video mappings':'Run actual mapper and Video output checks';$('#video-midi-status').textContent='Ready';}
$('#video-midi-run').onclick=async()=>{const b=$('#video-midi-run');b.disabled=true;try{await run();}catch(e){$('#video-midi-status').textContent='Harness error: '+e.message;}finally{b.disabled=false;}};init().catch(e=>$('#video-midi-status').textContent='Load failed: '+e.message);
